-- SELECT-only. Prove canonical swzpzcwiasxmjutrmvkm before connecting. No business rows.
SELECT p.oid::regprocedure,md5(pg_get_functiondef(p.oid)),pg_get_functiondef(p.oid),p.proacl,p.proconfig,p.prosecdef,p.provolatile,pg_get_userbyid(p.proowner) FROM pg_proc p WHERE p.oid IN ('platform_private.platform_actor_access_ready(uuid)'::regprocedure,'platform_private.h15_actor_organization()'::regprocedure,'platform_private.has_role(uuid,app_role)'::regprocedure,'public.h15_actor_organization()'::regprocedure,'public.has_role(uuid,app_role)'::regprocedure,'public.fn_authz_uid_scope_ok(uuid)'::regprocedure,'public.is_operational_staff(uuid)'::regprocedure,'public.get_cliente_ids_for_user(uuid)'::regprocedure,'public.rpc_salvar_aplicacao_v1(uuid,jsonb,uuid,jsonb,uuid[])'::regprocedure,'public.can_user_access_aplicacao(uuid)'::regprocedure);
SELECT c.oid::regclass,c.relacl,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) FROM pg_class c WHERE c.oid IN ('public.aplicacoes'::regclass,'public.ordens_servico'::regclass,'public.ordens_servico_onfarm'::regclass,'public.clientes'::regclass);
SELECT attrelid::regclass,attname,format_type(atttypid,atttypmod),attnotnull FROM pg_attribute WHERE attrelid IN ('public.aplicacoes'::regclass,'public.ordens_servico'::regclass,'public.ordens_servico_onfarm'::regclass,'public.clientes'::regclass) AND attnum>0 AND NOT attisdropped ORDER BY attrelid,attnum;
SELECT conrelid::regclass,conname,pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid IN ('public.aplicacoes'::regclass,'public.ordens_servico'::regclass,'public.ordens_servico_onfarm'::regclass,'public.clientes'::regclass) ORDER BY conrelid,conname;
SELECT * FROM pg_policies WHERE schemaname='public' AND tablename IN ('aplicacoes','ordens_servico','ordens_servico_onfarm','clientes') ORDER BY tablename,policyname;
SELECT tgrelid::regclass,tgname,pg_get_triggerdef(oid) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN ('public.aplicacoes'::regclass,'public.ordens_servico'::regclass,'public.ordens_servico_onfarm'::regclass,'public.clientes'::regclass) ORDER BY tgrelid,tgname;
